head.script:
scwin.onLoadComplete = function() {
    dataList1.setJSON([{
        "col1": "AAAA",
        "col2": "20160205",
        "col3": "201301",
        "col4": "20110205",
        "col5": "20110205"
    }]);
    dataList2.setJSON([{
        "col1": "AAAA",
        "col2": "20160205",
        "col3": "201301",
        "col4": "20110205",
        "col5": "20110205"
    }]);
};
scwin.gridView1_onviewchange = function(info) {
    alert("onviewchange fire1 ==: \n" + JSON.stringify(info, null, 4));
    var colID = gridView1.getColumnID(info.colIndex);
    dataList1.setCellData(info.rowIndex, colID, info.oldValue);
    alert("dataList set 값 확인 ==: " + dataList1.getCellData(info.rowIndex, colID));
};
scwin.gridView2_onviewchange = function(info) {
    //alert("onviewchange fire2 ==: \n" + JSON.stringify(info, null, 4));
    data = info;
	debugger;
    var colID = gridView2.getColumnID(info.colIndex);
    dataList2.setCellData(info.rowIndex, colID, info.oldValue);
    //alert("dataList set 값 확인 ==: " + dataList2.getCellData(info.rowIndex, colID));
};
scwin.customDateFormatter = function(value, formattedValue, rowIndwx, colIndex) {
    return value;
};
scwin.displayDateFormatter = function(value) {
    return value;
};
scwin.checkVal1 = function() {
	return data.oldValue == '20160205';
}
scwin.checkVal2 = function() {
	return data.oldValue == '20160205';
}
scwin.unitTest = function() {
    //init
	WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView2_cell_0_0_calendar_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mf_mf_gridView2_cell_0_0_calendar_calendar_cell_2_6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", 'true');
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. 날짜를 지우고 직접 입력하고 Focus Out 한다.
    //5. Clear the date, enter it directly and focus out.
    //Verify step 5. The corresponding onviewchange event is applied and a pop-up is generated. (info.oldValue) (info.newValue value is used instead of info.oldValue value.)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView2_cell_0_0_calendar_input').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView2_cell_0_0_calendar_input').value = '20160220'");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView2_cell_0_0_calendar_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", 'true');
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.data = null;
    scwin.onLoadComplete();
}
